// Define the scalar types similar to NumPy dtypes
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyScalarType {
    Int64,
    Float64,
    Complex128,
    String,
    Bool,
}

// Define the different types of objects that can be passed
#[derive(Debug)]
pub enum NumpyObject {
    Integer(i64),
    Float(f64),
    IntArray(Vec<i64>),
    FloatArray(Vec<f64>),
    ComplexArray(Vec<(f64, f64)>), // pairs of (real, imag)
    String(String),
    Boolean(bool),
    Generic,
}

fn obj2sctype(rep: NumpyObject, default: Option<NumpyScalarType>) -> Option<NumpyScalarType> {
    match rep {
        // Integer value -> Int64
        NumpyObject::Integer(_) => Some(NumpyScalarType::Int64),
        
        // Floating-point value -> Float64
        NumpyObject::Float(_) => Some(NumpyScalarType::Float64),
        
        // Array of integers -> Int64
        NumpyObject::IntArray(_) => Some(NumpyScalarType::Int64),
        
        // Array of floats -> Float64
        NumpyObject::FloatArray(_) => Some(NumpyScalarType::Float64),
        
        // Array of complex pairs -> Complex128
        NumpyObject::ComplexArray(_) => Some(NumpyScalarType::Complex128),
        
        // String value -> String
        NumpyObject::String(_) => Some(NumpyScalarType::String),
        
        // Boolean value -> Bool
        NumpyObject::Boolean(_) => Some(NumpyScalarType::Bool),
        
        // Generic object -> use the provided default
        NumpyObject::Generic => default,
    }
}